// A neutral event parsed from one streamed payload.
struct StreamEvent
{
    // Failed: the model declined to answer. ServiceError: the service said
    // the reply failed, ended it early, or sent what cannot be read; the loop
    // stops the turn and reports what it sent.
    enum class Kind { TextDelta, TurnComplete, Failed, ServiceError };
    Kind                          kind{Kind::TextDelta};
    // TextDelta: the text. ServiceError: what the service said, for a report.
    std::string                   text;
    nlohmann::json                assistant_turn; // TurnComplete, opaque to the loop
    std::vector<ProviderToolCall> calls;          // TurnComplete
    std::optional<AgentUsage>     usage;          // TurnComplete, when the provider reported it
    // TurnComplete: the provider paused its turn and continues it when the
    // same request is sent again with this turn appended (Anthropic's
    // pause_turn). It has no calls.
    bool                          resend{false};
    AgentError                    error;          // Failed
};

struct ProviderRequest
{
    nlohmann::json               body;
    std::vector<AgentHttpHeader> headers;
};

class IProviderCodec
{
public:
    virtual ~IProviderCodec() = default;

    virtual ProviderRequest build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const = 0;

    // Called before each request's stream; a codec that accumulates partial
    m_first_usage = json();
    m_last_usage = json();
    m_model.clear();
    m_started = std::chrono::steady_clock::now();
}

std::vector<StreamEvent> AnthropicCodec::parse(const std::string& payload)
{
    std::vector<StreamEvent> events;
    // Never an error a person can act on: the loop stops the turn with what
    // the service sent.
    const auto               failed = [&events](std::string text) {
        StreamEvent event;
        event.kind = StreamEvent::Kind::ServiceError;
        event.text = std::move(text);
        events.push_back(std::move(event));
    };
    const json event = json::parse(payload, nullptr, false);
    if (!event.is_object()) {
        failed("sent an event that is not JSON: " + payload);
        return events;
        event.error = {"refusal", Slic3r::format(translated(L("The AI service declined to answer (%1%).")), category), false};
        return event;
    }
    if (m_stop_reason != "end_turn" && m_stop_reason != "tool_use" && m_stop_reason != "stop_sequence" &&
        m_stop_reason != "pause_turn") {
