        event.kind = StreamEvent::Kind::ServiceError;
        event.text = "ended its response with the stop reason \"" + m_stop_reason + "\"";
        return event;
    }
    event.kind           = StreamEvent::Kind::TurnComplete;
    event.assistant_turn = json::array();
