#pragma once

// The provider-neutral turn loop behind IAgentService. It owns the
// transcript of the turn: the chat's record, then what the turn adds, which
// it hands back to the record once a later request can follow on from it.
// It runs the model's tool calls one at a time in the order written, answers
// the rest unrun after a failure, refuses calls to tools not offered or with
// arguments off the contract, and sends fired skills after what fired them.
// Everything on the wire goes through the IProviderCodec it is built with,
// and nothing here reads provider JSON.
//
// Network callbacks only append protected input; all parsing and AgentEvent
// delivery happens from poll() on the GUI thread.

#include "AgentService.hpp"
#include "AgentTransport.hpp"
#include "ProviderCodec.hpp"
#include "ProviderProfile.hpp"

#include <deque>
#include <functional>
#include <memory>
#include <mutex>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// A request about to be sent. The headers stay out: they hold the credential.
struct SentRequest
{
    std::string           provider;
    std::string           chat_key; // empty for a request of no chat
    std::string           turn_id;
    unsigned              sequence{0}; // which request of the turn, from 1
    const nlohmann::json& body;
};

// The name JusPrin's gateway keeps a chat's turns and credits under, sent as
// X-JusPrin-Chat: the chat key hashed, so the gateway never sees a project or
// chat id.
std::string gateway_chat_id(const std::string& chat_key);

// An AI service's answer that names nothing a person can act on, in the
// service's own words: its status or event, its request id, and the turn the
// request belonged to. poll() throws it where the answer is read, after
// stopping the request; the top handler of the pump that polled reports it
// (AgentHost::pump_stream, AgentHost::pump_setup).
class UnexpectedServiceAnswer : public std::runtime_error
{
public:
    using std::runtime_error::runtime_error;
};

struct ProviderAgentConfig
{
    // The provider, with the configured model and endpoint in place of the
    // row's defaults where the person set them.
    ProviderProfile profile;
    std::string     api_key;
    std::function<void(const AgentUsage&)> usage_listener;
    // A tool call the loop refused before it reached a card: the tool name,
    // the arguments as the model sent them, and why.
    std::function<void(const std::string&, const std::string&, const std::string&)> refusal_listener;
    std::function<void(const SentRequest&)> request_listener;
};

class ProviderAgent : public IAgentService
{
public:
    ProviderAgent(ProviderAgentConfig config, std::unique_ptr<IProviderCodec> codec, std::unique_ptr<IAgentHttpTransport> transport);
    ~ProviderAgent() override;

    bool ready() const override;
    bool busy() const override;
    bool start(const AgentRequest& request) override;
    bool continue_after_tool(const AgentToolResult& result) override;
    void cancel() override;
    std::optional<AgentEvent> poll() override;

private:
    struct QueuedHttpEvent
    {
        std::uint64_t generation{0};
        AgentHttpEvent event;
    };

    void begin_transcript(const AgentRequest& request);
    bool m_app_started{false};
    void push_skills(const std::vector<AgentSkillUse>& skills, std::vector<RecordItem> notes = {});
    // The part with its blob written, ahead of the request that first sends it.
    RecordPart kept(RecordPart part);
    // Hands the chat's record what the provider accepted and is settled.
    void record();
    void post();
    void accept_http(std::uint64_t generation, AgentHttpEvent event);
    void parse_available();
    void parse_sse_frame(const std::string& frame);
    void handle(StreamEvent event);
    void finish_response(StreamEvent event);
    void next_call();
    void answer_call(const std::string& call_id, const nlohmann::json& output);
    void fail(AgentError error);
    // The error a person can act on that an answer names (see
    // ProviderAgent.cpp); each throws UnexpectedServiceAnswer when none does.
    AgentError http_error(const AgentHttpEvent& event);
    std::optional<AgentError> gateway_answer(const std::string& code, const std::string& body) const;
    std::optional<AgentError> provider_answer(unsigned status) const;
    // Stops the request and throws what the service answered.
    [[noreturn]] void unexpected(const std::string& answered, const std::string& words);

    ProviderAgentConfig                   m_config;
    std::unique_ptr<IProviderCodec>       m_codec;
    std::unique_ptr<IAgentHttpTransport>  m_transport;
    mutable std::mutex                    m_mutex;
    std::deque<QueuedHttpEvent>           m_http_events;
    std::deque<AgentEvent>                m_events;
    std::string                           m_sse_buffer;
    // What the model has been told; every request is built from it.
    TurnTranscript                        m_transcript;
    // Where the turn's items go to be kept, and how far they have gone: the
    // items before m_recorded are in the chat's record. Those before
    // m_settled join it once the provider accepts a request carrying them: a
    // request may fail after them and the next one still follows on (never a
    // call without its result, never an operator message with nothing after
    // it).
    std::function<void(const std::string&, std::vector<RecordItem>)> m_on_recorded;
    std::function<std::string(const std::string&)>                   m_keep_blob;
    std::size_t                           m_recorded{0};
    std::size_t                           m_settled{0};
    // The results of the response's calls so far.
    RecordItem                            m_results{RecordItem::Kind::Results};
    RequestKind                           m_kind{RequestKind::Reply};
    std::string                           m_pending_call_id;
    std::string                           m_pending_tool;
    // A response may hold several calls. They run one at a time, in the
    // order the model wrote them, and every one gets a result; the results
    // go back together in one request once the last has its answer.
    std::deque<ProviderToolCall>          m_queued_calls;
    // The skills the response's results fired, sent after all of them on the
    // next request only; one per name, the latest kept.
    std::vector<AgentSkillUse>            m_step_skills;
    // The first call of this response that did not succeed, as "tool
    // (call_id)"; every call after it is answered without being run.
    std::string                           m_failed_call;
    unsigned                              m_rejected_calls{0};
    unsigned                              m_paused_turns{0};
    std::uint64_t                         m_http_generation{0};
    // The service's id for the request in flight, once its headers came.
    std::string                           m_service_request_id;
    bool                                  m_busy{false};
    bool                                  m_waiting_for_tool{false};
    bool                                  m_terminal_seen{false};
};

} // namespace Slic3r::GUI::JusPrin::Agent

